#!/usr/bin/env python3
"""
Proof-of-Concept: Inconsistent Principal Name Canonicalization (RFC 4120)

This script demonstrates how inconsistent canonicalization of Kerberos principal names
can lead to authentication bypass. The RFC states implementations MUST NOT use insecure
DNS for canonicalization, but notes many do, and there's no consistency in case-folding
or reverse resolution.

The PoC simulates:
1. A client crafting a principal name with mixed case and an alias.
2. A vulnerable server/KDC that applies different canonicalization rules than the client.
3. The resulting mismatch that allows impersonation.
"""

import socket
import struct
import sys
import threading
import time

# --- Kerberos Principal Name Constants (simplified for PoC) ---
# In real Kerberos, principal names are structured as (realm, name-string)
# name-string is a sequence of strings. We'll simulate the parsing logic.

def canonicalize_client_style(principal_name):
    """
    Simulates a client that folds to lowercase and does NOT do DNS lookups.
    This is the secure/recommended behavior per RFC 4120.
    """
    # Client folds everything to lowercase
    return principal_name.lower()

def canonicalize_server_style_vulnerable(principal_name):
    """
    Simulates a vulnerable server/KDC that:
    1. Does NOT fold to lowercase (case-sensitive comparison)
    2. Performs an insecure DNS lookup to resolve aliases
    
    This mismatch allows an attacker to craft a name that the client thinks
    is 'host/secure-server.example.com' but the server resolves to
    'host/attacker-controlled.example.com'.
    """
    # Simulate insecure DNS lookup: attacker controls DNS, maps alias to malicious host
    dns_mapping = {
        'secure-server.example.com': 'attacker-controlled.example.com',
        'Web-App.Example.COM': 'web-app.example.com' # Case mismatch
    }
    
    # Extract hostname part (simplified: assume format 'service/hostname')
    if '/' in principal_name:
        service, hostname = principal_name.split('/', 1)
        # Vulnerable: DNS lookup without validation
        if hostname in dns_mapping:
            hostname = dns_mapping[hostname]
        # Vulnerable: No case folding, keeps original case
        return f"{service}/{hostname}"
    return principal_name

def canonicalize_server_style_patched(principal_name):
    """
    Simulates a patched server that strictly enforces lowercase canonicalization
    and does not perform insecure DNS lookups.
    """
    # Strictly fold to lowercase, no DNS
    return principal_name.lower()

def craft_exploit_principal(target_service, target_host):
    """
    Attacker crafts a principal name that exploits canonicalization differences.
    
    Strategy 1: Case mismatch. Client sends 'host/Web-App.Example.COM'.
    Client canonicalizes to 'host/web-app.example.com'.
    Vulnerable server keeps case: 'host/Web-App.Example.COM' != 'host/web-app.example.com'
    
    Strategy 2: DNS alias. Client sends 'host/secure-server.example.com'.
    Client canonicalizes to 'host/secure-server.example.com'.
    Vulnerable server DNS-resolves to 'host/attacker-controlled.example.com'.
    """
    # We'll demonstrate the DNS alias attack as it's more impactful
    return f"host/{target_host}"

def simulate_kerberos_exchange(client_principal, server_principal, server_canonicalizer):
    """
    Simulates the core of a Kerberos authentication exchange where principal names
    are compared. In reality, this happens during TGS-REQ/REP or AP-REQ/AP-REP.
    """
    print(f"[CLIENT] Requesting ticket for: {client_principal}")
    client_canonical = canonicalize_client_style(client_principal)
    print(f"[CLIENT] Canonicalized to: {client_canonical}")
    
    print(f"[SERVER] Received principal: {server_principal}")
    server_canonical = server_canonicalizer(server_principal)
    print(f"[SERVER] Canonicalized to: {server_canonical}")
    
    # Authentication decision
    if client_canonical == server_canonical:
        return True, "Authentication SUCCESSFUL"
    else:
        return False, "Authentication FAILED"

def main():
    print("="*60)
    print("Kerberos Principal Name Canonicalization PoC")
    print("="*60)
    
    # Target service the client INTENDS to contact
    intended_service = "host/secure-server.example.com"
    
    # Attacker crafts a principal name
    # In a real attack, the attacker might control DNS to map 'secure-server.example.com'
    # to their own machine, or exploit case sensitivity.
    crafted_principal = "host/secure-server.example.com"
    
    print("\n--- Scenario 1: Vulnerable Server (Insecure DNS + No Case Folding) ---")
    print(f"Client intends to contact: {intended_service}")
    print(f"Attacker crafts principal: {crafted_principal}")
    
    # Simulate exchange with vulnerable server
    auth_result, status = simulate_kerberos_exchange(
        crafted_principal, 
        crafted_principal, 
        canonicalize_server_style_vulnerable
    )
    print(f"[RESULT] {status}")
    if not auth_result:
        print("[VULN] Canonicalization mismatch detected! Server and client disagree on identity.")
        print("[VULN] Attacker can exploit this to impersonate the service or bypass checks.")
    
    print("\n--- Scenario 2: Patched Server (Strict Lowercase, No DNS) ---")
    print(f"Client intends to contact: {intended_service}")
    print(f"Attacker crafts principal: {crafted_principal}")
    
    # Simulate exchange with patched server
    auth_result, status = simulate_kerberos_exchange(
        crafted_principal, 
        crafted_principal, 
        canonicalize_server_style_patched
    )
    print(f"[RESULT] {status}")
    if auth_result:
        print("[SAFE] Canonicalization consistent. Authentication proceeds normally.")
    
    print("\n--- Scenario 3: Case-Sensitivity Exploit ---")
    case_principal = "host/Web-App.Example.COM"
    print(f"Client sends: {case_principal}")
    
    auth_result, status = simulate_kerberos_exchange(
        case_principal, 
        case_principal, 
        canonicalize_server_style_vulnerable
    )
    print(f"[RESULT] {status}")
    if not auth_result:
        print("[VULN] Case mismatch allows bypass. Client thinks it's talking to 'web-app.example.com',")
        print("       but server sees 'Web-App.Example.COM'. If server grants access based on")
        print("       the latter, attacker bypasses intended access controls.")
    
    print("\n" + "="*60)
    print("PoC Complete. Review output for canonicalization mismatches.")
    print("="*60)

if __name__ == "__main__":
    main()
